  /** Removes the current list item based on the iterator position. */
  public void remove() {
    if (curr == null) return;

    size--;

    Item<T> c = curr;
    Item<T> n = curr.next;
    Item<T> p = curr.prev;
    pool.free(curr);
    curr = null;

    if (size == 0) {
